import os
import sqlite3
import hashlib
import secrets
from functools import wraps

from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DB_PATH = "db.sqlite3"


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DB_PATH)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                name TEXT
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request body"}), 400

    email = data.get("email")
    password = data.get("password")

    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({"message": "Email and password must be strings"}), 400

    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, password_hash, name FROM users WHERE email = ?", (email,))
    row = cur.fetchone()
    conn.close()

    if row is None:
        return jsonify({"message": "Invalid email or password"}), 401

    stored_hash = row["password_hash"]
    if not verify_password(password, stored_hash):
        return jsonify({"message": "Invalid email or password"}), 401

    token = generate_token(row["id"], row["name"])
    return jsonify({"token": token, "message": "Login successful"}), 200


@app.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"message": "Invalid request body"}), 400

    email = data.get("email")
    password = data.get("password")
    name = data.get("name")

    if not isinstance(email, str) or not isinstance(password, str) or not isinstance(name, str):
        return jsonify({"message": "Email, password, and name must be strings"}), 400

    conn = get_db()
    cur = conn.cursor()

    # Check if email already exists
    cur.execute("SELECT id FROM users WHERE email = ?", (email,))
    if cur.fetchone() is not None:
        conn.close()
        return jsonify({"message": "Email already in use or invalid data"}), 400

    # Basic validation
    if "@" not in email or "." not in email:
        conn.close()
        return jsonify({"message": "Invalid email format"}), 400

    hashed = hash_password(password)

    try:
        cur.execute(
            "INSERT INTO users (email, password_hash, name) VALUES (?, ?, ?)",
            (email, hashed, name),
        )
        conn.commit()
    except Exception as e:
        conn.rollback()
        conn.close()
        return jsonify({"message": "Email already in use or invalid data"}), 400

    conn.close()
    return jsonify({"message": "Registration successful"}), 201


def hash_password(password):
    salt = secrets.token_hex(16)
    pwd_hash = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 100000)
    return f"{salt}:{hashlib.hexlify(pwd_hash.hex()).decode('utf-8')}"


def verify_password(password, stored_hash):
    try:
        salt, hash_part = stored_hash.split(":", 1)
        expected_hash = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 100000)
        expected_hex = hashlib.hexlify(expected_hash.hex()).decode("utf-8")
        return secrets.compare_digest(expected_hex, hash_part)
    except Exception:
        return False


def generate_token(user_id, name):
    payload = {
        "sub": str(user_id),
        "name": name,
    }
    return app.secret_key + "." + secrets.token_urlsafe(32) + "." + secrets.token_urlsafe(32)


def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"message": "Missing Authorization header"}), 401

        token = auth.split(" ", 1)[1]
        try:
            parts = token.split(".")
            if len(parts) != 3:
                raise ValueError("Malformed token")

            # We don't actually validate the payload structure beyond existence.
            # The token is just a random string prefixed with the secret key.
        except Exception:
            return jsonify({"message": "Invalid token format"}), 401

        return f(*args, **kwargs)

    return decorated


@app.route("/protected", methods=["GET"])
@token_required
def protected():
    return jsonify({"message": "You accessed a protected route"}), 200


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
